const turbopackRoot = path.resolve(appDir, "../..");

// const turbopackRoot = path.dirname(fileURLToPath(import.meta.url));

const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";

const getRemotePatterns = () => {
  const patterns: Array<{
    protocol: RemotePattern["protocol"];
    hostname: RemotePattern["hostname"];
  }> = [];

  // Add extra domains via env (comma-separated)
  // Ex: NEXT_PUBLIC_ALLOWED_DOMAINS=example.com,cdn.example.com
  const extraDomains =
    process.env.NEXT_PUBLIC_ALLOWED_DOMAINS?.split(",") || [];

  extraDomains.forEach((domain) => {
    const trimmedDomain = domain.trim();
    if (trimmedDomain) {
      patterns.push(
        { protocol: "https" as const, hostname: trimmedDomain },
        { protocol: "http" as const, hostname: trimmedDomain },
      );
    }
  });

  return patterns;
};

const nextConfig: NextConfig = {
  output: "standalone",
  // Pin the standalone tracing root to THIS app. Without it, Next infers a
  // monorepo root above the app (multiple lockfiles up the tree) and nests the
  // build — server.js lands in `.next/standalone/app/server.js` instead of the
  // root, so the Docker image's `node server.js` @ /app crashes (MODULE_NOT_FOUND).
  outputFileTracingRoot: appDir,
  basePath: basePath,
  images: {
