  output: "standalone",
  basePath: basePath,
  redirects: getRedirects,
  images: {
    remotePatterns: getRemotePatterns(),
  },
  typedRoutes: true,
  turbopack: {
    root: turbopackRoot,
    resolveAlias: {
      "lucide-react/dynamicIconImports": lucideDynamicIconImports,
    },
