    authInterrupts: true,
    typedEnv: true,
    browserDebugInfoInTerminal: {
      depthLimit: 5,
      edgeLimit: 1000,
    },
    optimizePackageImports: [
      "@igrp/igrp-framework-react-design-system",
      "@igrp/framework-next-ui",
      "@igrp/framework-next",
      "@tanstack/react-query",
    ],
  },
};

