  const nextWithPath = (): NextResponse => {
    const requestHeaders = new Headers(request.headers);
    requestHeaders.set("x-current-path", currentPath);
    return withSecurityHeaders(
      NextResponse.next({ request: { headers: requestHeaders } }),
    );
  };

