  { key: "feature", path: "src/app/(myapp)/_features/<módulo>/" },
  { key: "route", path: "src/app/(igrp)/<rota>/page.tsx" },
  { key: "guard", path: 'await igrpAssertAuthorize("<permissão>")' },
