        </h1>
        <p className="max-w-[60ch] text-lg text-pretty text-muted-foreground">
          {failing > 0
            ? t("intro.failing", { count: failing })
            : previewMode
              ? t("intro.preview")
              : t("intro.ok")}
        </p>
